/**
 * The Guardian's own signing key. It is generated by this browser and marked
 * non-extractable, so neither this code nor the platform can read it. IndexedDB
 * keeps only the opaque CryptoKey handle; it is not exportable from there.
 *
 * Clearing browser data loses the key. The Guardian then binds a new one with a
 * fresh challenge, after the same delay as any other Guardian change.
 */

const DATABASE = "secure-ssi-guardian";
const STORE = "device-keys";
const ALPHABET = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";

export interface GuardianDeviceKey {
  did: string;
  verificationMethod: string;
  sign(data: Uint8Array): Promise<Uint8Array>;
}

export type GuardianSigner = () => Promise<GuardianDeviceKey>;

function base58(bytes: Uint8Array): string {
  let number = 0n;
  for (const byte of bytes) number = number * 256n + BigInt(byte);
  let encoded = "";
  while (number > 0n) {
    encoded = ALPHABET[Number(number % 58n)] + encoded;
    number /= 58n;
  }
  for (const byte of bytes) {
    if (byte !== 0) break;
    encoded = "1" + encoded;
  }
  return encoded;
}

export function didKeyFromPublicKey(publicKey: Uint8Array): { did: string; verificationMethod: string } {
  const prefixed = new Uint8Array(publicKey.length + 2);
  prefixed.set([0xed, 0x01]);
  prefixed.set(publicKey, 2);
  const multibase = `z${base58(prefixed)}`;
  const did = `did:key:${multibase}`;
  return { did, verificationMethod: `${did}#${multibase}` };
}

async function wrapPair(pair: CryptoKeyPair): Promise<GuardianDeviceKey> {
  const raw = new Uint8Array(await crypto.subtle.exportKey("raw", pair.publicKey));
  return {
    ...didKeyFromPublicKey(raw),
    sign: async (data) => new Uint8Array(await crypto.subtle.sign("Ed25519", pair.privateKey, data as BufferSource)),
  };
}

function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DATABASE, 1);
    request.onupgradeneeded = () => request.result.createObjectStore(STORE);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function storeRequest<T>(mode: IDBTransactionMode, run: (store: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  return openDatabase().then((database) => new Promise<T>((resolve, reject) => {
    const request = run(database.transaction(STORE, mode).objectStore(STORE));
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  }));
}

export async function findDeviceKey(userId: string): Promise<GuardianDeviceKey | null> {
  const stored = await storeRequest<CryptoKeyPair | undefined>("readonly", (store) => store.get(userId));
  return stored ? wrapPair(stored) : null;
}

/** Creates a new key, replacing any earlier one for this account on this browser. */
export async function createDeviceKey(userId: string): Promise<GuardianDeviceKey> {
  const pair = await crypto.subtle.generateKey("Ed25519", false, ["sign", "verify"]) as CryptoKeyPair;
  await storeRequest("readwrite", (store) => store.put(pair, userId));
  return wrapPair(pair);
}

export async function getOrCreateDeviceKey(userId: string): Promise<GuardianDeviceKey> {
  return (await findDeviceKey(userId)) ?? createDeviceKey(userId);
}

function base64Url(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

const encodeJson = (value: unknown): string => base64Url(new TextEncoder().encode(JSON.stringify(value)));

/** A compact EdDSA JWT, signed locally. No claim or signature leaves unsigned. */
export async function signGuardianJwt(
  key: GuardianDeviceKey,
  type: "guardian-binding+jwt" | "guardian-recovery+jwt",
  claims: Record<string, unknown>,
): Promise<string> {
  const issuedAt = Math.floor(Date.now() / 1000);
  const tokenId = base64Url(crypto.getRandomValues(new Uint8Array(18)));
  const input = `${encodeJson({ alg: "EdDSA", typ: type, kid: key.verificationMethod })}.${encodeJson({
    ...claims,
    iss: key.did,
    aud: "secure-ssi-platform:guardian-recovery",
    iat: issuedAt,
    exp: issuedAt + 120,
    jti: tokenId,
  })}`;
  const signature = await key.sign(new TextEncoder().encode(input));
  return `${input}.${base64Url(signature)}`;
}
